INSERT INTO `portfolio_items` VALUES (34,'Sales Performance Command Center','Power BI Dashboard','Executive dashboard for daily sales, margin, and regional contribution analysis.','Built a semantic model with territory and product dimensions, plus drill-through pages for sales managers to investigate underperforming segments quickly.','https://example.com/powerbi-sales-command-center','http://127.0.0.1:8000/storage/uploads/portfolio/7ae1a2b8-29df-4395-a9f8-08b3b8b2d3d2.png',1,1,2,'2026-03-23 16:12:22','2026-03-23 16:44:40'),(35,'Finance KPI Suite for CFO Office','Power BI Dashboard','A full finance dashboard suite covering revenue, OPEX, EBITDA, and variance analysis.','Implemented standardized DAX measures and month-end reconciliation views to align finance reporting across planning, accounting, and leadership teams.','https://example.com/powerbi-finance-kpi-suite','http://localhost/storage/uploads/portfolio/seed-portfolio-2.svg',2,1,0,'2026-03-23 16:12:22','2026-03-23 16:12:22'),(36,'Inventory Health & Forecast Dashboard','Power BI Analytics','Monitors stock aging, stockout risk, and demand forecasts in one operational view.','Combined ERP data and forecast assumptions to surface reorder priorities and reduce excess stock while maintaining service levels.','https://example.com/powerbi-inventory-health','http://localhost/storage/uploads/portfolio/seed-portfolio-3.svg',3,1,0,'2026-03-23 16:12:22','2026-03-23 16:12:22'),(37,'HR Workforce Analytics Dashboard','People Analytics','Tracks hiring funnel, turnover, and workforce composition for HR strategy.','Designed role-based views for HRBP, recruiters, and leadership with reliable monthly snapshots and trend metrics.','https://example.com/powerbi-hr-workforce-analytics','http://localhost/storage/uploads/portfolio/seed-portfolio-4.svg',4,1,1,'2026-03-23 16:12:22','2026-03-23 16:40:38'),(38,'Power Apps Field Audit Solution','Power Apps','Mobile app for field teams to submit structured audit findings in real time.','Built validation rules, photo capture, and offline-friendly forms. Data feeds directly into Power BI for compliance and quality tracking.','https://example.com/powerapps-field-audit','http://localhost/storage/uploads/portfolio/seed-portfolio-5.svg',5,1,0,'2026-03-23 16:12:22','2026-03-23 16:12:22'),(39,'Procurement Request App with Approval Flow','Power Apps + Power Automate','End-to-end procurement request app with approval routing and SLA visibility.','Integrated Power Apps forms, approval workflows, and Power BI monitoring to reduce cycle time and improve procurement governance.','https://example.com/powerapps-procurement-flow','http://localhost/storage/uploads/portfolio/seed-portfolio-6.svg',6,1,0,'2026-03-23 16:12:22','2026-03-23 16:12:22'),(40,'Service Desk SLA Monitoring','Operational Analytics','SLA and ticket flow analytics for IT service management teams.','Implemented queue aging, breach prediction, and workload balancing visuals to improve response time and customer satisfaction.','https://example.com/service-desk-sla-monitoring','http://localhost/storage/uploads/portfolio/seed-portfolio-7.svg',7,1,0,'2026-03-23 16:12:22','2026-03-23 16:12:22'),(41,'Power BI Governance & Adoption Program','BI Strategy','Governance blueprint with workspace standards, certification flow, and adoption metrics.','Developed a scalable governance operating model and measured adoption through active user, report quality, and business outcome indicators.','https://example.com/powerbi-governance-adoption','http://localhost/storage/uploads/portfolio/seed-portfolio-8.svg',8,1,0,'2026-03-23 16:12:22','2026-03-23 16:12:22');
