INSERT INTO `slides` VALUES (19,'Data Analytics for Better Decisions','Turn raw data into clear insights that accelerate business decisions.','http://localhost/storage/uploads/slide/seed-slide-1.svg','Explore Dashboard','http://localhost/portfolio',1,1,'2026-03-23 16:12:22','2026-03-23 16:12:22'),(20,'Real-Time KPI Monitoring','Monitor team and product performance in real time through clear data visualizations.','http://localhost/storage/uploads/slide/seed-slide-2.svg','View Portfolio','http://localhost/portfolio',2,1,'2026-03-23 16:12:22','2026-03-23 16:12:22'),(21,'Predictive Insights & Growth','Use historical trends to predict new opportunities and strengthen growth strategy.','http://localhost/storage/uploads/slide/seed-slide-3.svg','Read Blog','http://localhost/blog',3,1,'2026-03-23 16:12:22','2026-03-23 16:12:22'),(22,'Build Faster, Ship Cleaner','Web engineering and analytics implementation with practical architecture.','http://localhost/storage/uploads/slide/seed-slide-4.svg','Contact Me','http://localhost/profile',4,1,'2026-03-23 16:12:22','2026-03-23 16:12:22');
